import json
import math
import os
import re
import sys
from datetime import datetime, timedelta, timezone

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
EPOCH = datetime(1970, 1, 1)
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")


def convert(quantity, unit, value):
    if quantity == "temp":
        if unit == "degF":
            return (value - 32) * 5 / 9
        if unit == "K":
            return value - 273.15
    elif quantity == "rh":
        if unit == "frac":
            return value * 100
    elif quantity == "pres":
        if unit == "kPa":
            return value * 10
        if unit == "inHg":
            return value * 33.8638866667
        if unit == "mmHg":
            return value * 1.33322387415
    elif quantity == "wspd":
        if unit == "kmh":
            return value / 3.6
        if unit == "kn":
            return value * 1852 / 3600
        if unit == "mph":
            return value * 0.44704
    elif quantity == "rain":
        if unit.startswith("tips:"):
            return value * float(unit[5:])
    return value


def parse_time(text):
    text = text.strip().replace("T", " ")
    return datetime.strptime(text, "%Y-%m-%d %H:%M:%S")


def seconds(moment):
    return int((moment - EPOCH).total_seconds())


def parse_tz(text):
    text = text.strip()
    if text in ("Z", "z"):
        return 0
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return sign * (int(hours) * 3600 + int(minutes) * 60)


def parse_number(field):
    field = field.strip()
    if field == "" or field == "---" or field.lower() == "nan":
        return None
    try:
        value = float(field)
    except ValueError:
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    if value == -9999:
        return None
    return value


def read_file(path):
    with open(path, "rb") as handle:
        text = handle.read().decode("utf-8-sig")
    info = {"station": None, "upload": 0, "interval": None, "tz": 0}
    columns = None
    units = {}
    rows = []
    syncs = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line.startswith("#"):
            match = DIRECTIVE.match(line)
            if not match:
                continue
            key, value = match.group(1), match.group(2).strip()
            if key == "station":
                info["station"] = value
            elif key == "upload":
                info["upload"] = int(value)
            elif key == "interval":
                info["interval"] = int(float(value))
            elif key == "tz":
                info["tz"] = parse_tz(value)
            elif key == "columns":
                columns = [name.strip() for name in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        name, unit = pair.split("=", 1)
                        units[name] = unit
            elif key == "sync":
                parts = {}
                for part in value.split():
                    if "=" in part:
                        name, content = part.split("=", 1)
                        parts[name] = content
                if "logger" in parts and "ref" in parts:
                    logger = parse_time(parts["logger"])
                    ref = datetime.strptime(parts["ref"], "%Y-%m-%dT%H:%M:%SZ")
                    syncs.append((logger, ref))
            continue
        if columns is None:
            continue
        fields = [field.strip() for field in line.split(",")]
        row = {}
        logger_time = None
        for name, field in zip(columns, fields):
            if name == "time":
                logger_time = parse_time(field)
            elif name in RANGES:
                value = parse_number(field)
                if value is not None:
                    value = convert(name, units.get(name, ""), value)
                    low, high = RANGES[name]
                    if not (low <= value <= high):
                        value = None
                row[name] = value
        rows.append((logger_time, row, set(name for name in columns if name in RANGES)))
    return info, rows, syncs


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    stations = {}
    for name in sorted(os.listdir(input_dir)):
        path = os.path.join(input_dir, name)
        if not name.endswith(".log") or not os.path.isfile(path):
            continue
        info, rows, syncs = read_file(path)
        if info["station"] is None:
            continue
        entry = stations.setdefault(info["station"], {"interval": info["interval"], "rows": {}, "syncs": {}})
        if entry["interval"] is None:
            entry["interval"] = info["interval"]
        offset = info["tz"]
        upload = info["upload"]
        for logger, ref in syncs:
            instant = seconds(logger) - offset
            current = entry["syncs"].get(instant)
            if current is None or upload >= current[0]:
                entry["syncs"][instant] = (upload, seconds(ref) - instant)
        for logger_time, row, present in rows:
            instant = seconds(logger_time) - offset
            current = entry["rows"].get(instant)
            if current is None or upload >= current[0]:
                entry["rows"][instant] = (upload, row)

    result = []
    for station in sorted(stations):
        entry = stations[station]
        if not entry["rows"]:
            continue
        interval = entry["interval"]
        points = sorted((instant, data[1]) for instant, data in entry["syncs"].items())

        def clock_offset(instant):
            if not points:
                return 0
            if instant <= points[0][0]:
                return points[0][1]
            if instant >= points[-1][0]:
                return points[-1][1]
            low, high = 0, len(points) - 1
            while high - low > 1:
                mid = (low + high) // 2
                if points[mid][0] <= instant:
                    low = mid
                else:
                    high = mid
            t1, o1 = points[low]
            t2, o2 = points[high]
            if instant == t1:
                return o1
            return o1 + ((o2 - o1) * (instant - t1)) // (t2 - t1)

        samples = []
        for instant, (upload, row) in entry["rows"].items():
            samples.append((instant + clock_offset(instant), instant, row))
        samples.sort(key=lambda item: (item[0], item[1]))

        hours = {}
        last_rain = None
        for corrected, instant, row in samples:
            hour = -((-corrected) // 3600)
            bucket = hours.setdefault(hour, {name: [] for name in QUANTITIES})
            bucket.setdefault("vectors", [])
            bucket.setdefault("rain_inc", [])
            for name in QUANTITIES:
                if row.get(name) is not None:
                    bucket[name].append(row[name])
            direction = row.get("wdir")
            speed = row.get("wspd")
            if direction is not None and speed is not None and speed > 0:
                bucket["vectors"].append(direction)
            rain = row.get("rain")
            if rain is not None:
                if last_rain is not None and 2 * (corrected - last_rain[0]) <= 5 * interval:
                    previous = last_rain[1]
                    bucket["rain_inc"].append(rain - previous if rain >= previous else rain)
                last_rain = (corrected, rain)

        expected = 3600 / interval
        first, last = min(hours), max(hours)
        hour_list = []
        for hour in range(first, last + 1):
            bucket = hours.get(hour)
            item = {"hour": (EPOCH + timedelta(seconds=hour * 3600)).strftime("%Y-%m-%dT%H:00:00Z")}
            for name in QUANTITIES:
                values = bucket[name] if bucket else []
                count = len(values)
                value = None
                if count * 4 >= expected * 3 and count > 0 or (count * 4 >= expected * 3 and name == "rain"):
                    if name == "wdir":
                        angles = bucket["vectors"]
                        if angles:
                            east = math.fsum(math.sin(math.radians(a)) for a in angles)
                            north = math.fsum(math.cos(math.radians(a)) for a in angles)
                            value = math.degrees(math.atan2(east, north)) % 360
                    elif name == "rain":
                        value = math.fsum(bucket["rain_inc"])
                    else:
                        value = math.fsum(values) / count
                if value is not None:
                    value = round(value, 2)
                    if name == "wdir" and value >= 360:
                        value = 0.0
                    value = value + 0.0
                item[name] = {"value": value, "n": count}
            hour_list.append(item)
        result.append({"station": station, "interval_s": interval, "hours": hour_list})

    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump({"stations": result}, handle, indent=1)


main()
